window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[257]={"id":"257","numero":257,"titre":"Œdèmes des membres inférieurs","objectifs":[{"id":"257-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des œdèmes","contenu":"<table >\n        <thead><tr><th>Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Œdème</strong></span></td>\n            <td><span class=\"kw-def\">Accumulation visible ou palpable de fluide</span> dans le <span class=\"kw-def\">tissu interstitiel</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Anasarque</strong></span></td>\n            <td>\n              Forme la plus grave, associe :\n              <ul>\n                <li><span class=\"kw-clinique\">Œdèmes généralisés</span></li>\n                <li>Épanchement des <span class=\"kw-clinique\">séreuses</span> : <span class=\"kw-clinique\">pleural</span> ± <span class=\"kw-clinique\">péritonéal (ascite)</span> ± <span class=\"kw-clinique\">péricardique</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p style=\"margin: 0 0 8px; font-size: 13px;\"><strong>Deux grands mécanismes (= deux démarches distinctes) :</strong></p>\n      <table >\n        <thead><tr><th>Type</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Œdème de cause locale</strong></span></td>\n            <td><span class=\"kw-etio\">Inflammation</span> ; <span class=\"kw-etio\">insuffisance veineuse</span> ; <span class=\"kw-etio\">insuffisance lymphatique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Œdème généralisé</strong></span></td>\n            <td><span class=\"kw-etio\">Hyperhydratation extracellulaire</span> — positivité de la <span class=\"kw-chiffre\">balance sodée et hydrique</span> (bilan sodé positif)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 267 — Troubles de l'hydratation (hyperhydratation extracellulaire)</em></p>","frequence":0},{"id":"257-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des œdèmes localisés","contenu":"<p style=\"margin: 0 0 10px; font-size: 13px;\">L'<span class=\"kw-clinique\">œdème</span> localisé résulte d'un <span class=\"kw-def\">déséquilibre local des forces de Starling</span> ou d'un <span class=\"kw-def\">défaut de drainage lymphatique</span>, sans positivité de la balance sodée globale.</p>\n      <table >\n        <thead><tr><th>Mécanisme local</th><th>Conséquence</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Inflammation</strong></span></td>\n            <td><span class=\"kw-clinique\">Augmentation de la perméabilité capillaire</span> → fuite de liquide vers l'interstitium</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Obstacle veineux</strong></span></td>\n            <td><span class=\"kw-clinique\">Augmentation de la pression hydrostatique</span> en aval (TVP, insuffisance veineuse)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Insuffisance lymphatique</strong></span></td>\n            <td><span class=\"kw-clinique\">Défaut de résorption lymphatique</span> de l'interstitium (lymphœdème)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p style=\"margin: 10px 0 6px; font-size: 13px;\"><strong>Particularités cliniques de l'<span class=\"kw-clinique\">œdème</span> localisé :</strong></p>\n      <ul>\n        <li><strong>Latéralité :</strong> <span class=\"kw-clinique\">unilatéral</span> ou <span class=\"kw-clinique\">asymétrique</span></li>\n        <li><strong>Topographie :</strong> <span class=\"kw-clinique\">moins bonne redistribution</span> en fonction de la déclivité</li>\n        <li><strong>Palpation :</strong> aspect parfois <span class=\"kw-clinique\">inflammatoire</span>, <span class=\"kw-clinique\">dur</span>, <span class=\"kw-clinique\">douloureux</span>, prenant <span class=\"kw-clinique\">moins bien le godet</span>, voire <span class=\"kw-clinique\">cartonné</span></li>\n      </ul>","frequence":0},{"id":"257-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des œdèmes généralisés","contenu":"<div class=\"callout callout-info\">\n        <strong>Définition (HEC).</strong> Augmentation du volume du compartiment <span class=\"kw-def\">extracellulaire</span> (surtout du secteur <span class=\"kw-def\">interstitiel</span>) par <span class=\"kw-chiffre\">rétention iso-osmotique de sodium et d'eau</span> (bilan sodé positif) — se traduit par des <span class=\"kw-clinique\">œdèmes généralisés</span>.\n      </div>\n      <table >\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Loi de Starling</strong></span></td>\n            <td>\n              Régit <span class=\"kw-clinique\">les</span> mouvements de l'eau et du sodium à travers la paroi capillaire :\n              <ul>\n                <li><span class=\"kw-clinique\">Pression hydrostatique</span> : favorise le passage d'eau du plasma vers l'interstitium</li>\n                <li><span class=\"kw-clinique\">Pression oncotique</span> (protéines) : favorise le maintien de l'eau dans le capillaire</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Régulation du capital sodé</strong></span></td>\n            <td>\n              La <span class=\"kw-chiffre\">quantité de sodium</span> (≠ concentration) détermine le VEC ; régulation assurée par le <strong>rein</strong>. <span class=\"kw-clinique\">Les</span> mécano-récepteurs vasculaires sensibles au volume sanguin « efficace » mettent en jeu :\n              <ul>\n                <li><span class=\"kw-clinique\">Systèmes natriurétiques</span> : <span class=\"kw-bio\">FAN</span>, <span class=\"kw-bio\">BNP</span>, prostaglandine E2, NO</li>\n                <li><span class=\"kw-clinique\">Systèmes anti-natriurétiques</span> : système sympathique, SRAA, endothélines, ADH</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Formation de l'œdème</strong></span></td>\n            <td>\n              <strong>Deux étapes nécessaires :</strong>\n              <ul>\n                <li>Passage des liquides du secteur vasculaire vers l'interstitium (<span class=\"kw-clinique\">↑ PH</span>, <span class=\"kw-clinique\">↓ PO</span>)</li>\n                <li><span class=\"kw-clinique\">Rétention rénale de sodium et d'eau</span></li>\n              </ul>\n              <strong>Localisation préférentielle :</strong> zones où la <span class=\"kw-bio\">PH</span> est maximale (<span class=\"kw-clinique\">zones déclives</span>) et où la contre-pression tissulaire est minimale (<span class=\"kw-clinique\">orbite de l'œil</span>, sujet jeune)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p style=\"margin: 12px 0 6px; font-size: 13px;\"><strong>Mécanismes selon l'étiologie (hypovolémie « efficace ») :</strong></p>\n      <table >\n        <thead><tr><th>Cause</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Syndrome néphrotique</strong></span></td>\n            <td>\n              <strong>Théorie du déficit de remplissage :</strong> <span class=\"kw-clinique\">perte d'albumine</span> → ↓ pression oncotique → fuite d'eau/Na vers l'interstitium → <span class=\"kw-clinique\">hypovolémie efficace</span> → activation du <span class=\"kw-clinique\">SRAA</span> → rétention d'eau et de Na<br>\n              <strong>Théorie de l'excès de remplissage :</strong> excès primaire de réabsorption distale du Na par le canal <span class=\"kw-clinique\">ENaC</span> (explique l'efficacité de l'amiloride)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Insuffisance cardiaque</strong></span></td>\n            <td>↓ débit cardiaque → <span class=\"kw-clinique\">hypovolémie efficace</span> → stimulation des systèmes anti-natriurétiques (sympathique, SRAA, endothéline) → ↓ excrétion rénale de Na → <span class=\"kw-clinique\">rétention hydrosodée</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Cirrhose</strong></span></td>\n            <td><span class=\"kw-clinique\">Hypovolémie efficace</span> : séquestration splanchnique en amont d'un obstacle post-sinusoïdal + vasodilatation périphérique ± hypoalbuminémie → activation des systèmes de réabsorption d'eau et de Na</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 267 — Hyperhydratation extracellulaire · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span> · 279 — Cirrhose · 259 — <span class=\"kw-bio\">Protéinurie</span> / <span class=\"kw-clinique\">syndrome néphrotique</span></em></p>","frequence":0},{"id":"257-4","rang":"A","rubrique":"Contenu multimédia","titre":"Photographies : aspect d'œdèmes de rétention hydrosodée, signe du godet","contenu":"<p style=\"margin: 0 0 10px; font-size: 13px;\">L'iconographie d'un <span class=\"kw-def\">œdème de rétention hydrosodée</span> montre des <span class=\"kw-clinique\">œdèmes</span> des membres inférieurs <span class=\"kw-clinique\">bilatéraux</span> et <span class=\"kw-clinique\">symétriques</span>, <span class=\"kw-clinique\">blancs</span>, <span class=\"kw-clinique\">mous</span> et <span class=\"kw-clinique\">indolores</span> — à l'opposé de l'<span class=\"kw-clinique\">œdème</span> localisé <span class=\"kw-etio\">inflammatoire</span> (rouge, dur, douloureux).</p>\n      <table >\n        <thead><tr><th>Signe à reconnaître</th><th>Description sémiologique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Signe du godet</strong></span> ⭐</td>\n            <td>La <span class=\"kw-clinique\">pression du doigt contre la face interne du tibia</span> laisse une <span class=\"kw-clinique\">dépression persistante</span> (godet) — signe l'<span class=\"kw-clinique\">œdème</span> <span class=\"kw-clinique\">mou</span> de rétention hydrosodée</td>\n          </tr>\n          <tr>\n            <td><strong>Topographie déclive</strong></td>\n            <td>Debout : <span class=\"kw-clinique\">chevilles</span> (effacement du sillon rétro-malléolaire), jambes ; alité : <span class=\"kw-clinique\">lombes</span>, région <span class=\"kw-clinique\">péri-orbitaire</span> chez le sujet jeune</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Caractères</strong></span></td>\n            <td><span class=\"kw-clinique\">Blancs</span>, <span class=\"kw-clinique\">indolores</span>, <span class=\"kw-clinique\">bilatéraux</span> et <span class=\"kw-clinique\">symétriques</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Iconographie.</strong> Le support photographique (aspect des <span class=\"kw-clinique\">œdèmes</span> de rétention, signe du godet) est à intégrer manuellement depuis la source (Collège CUEN). La description sémiologique ci-dessus couvre l'ensemble des signes attendus à l'identification.\n      </div>","frequence":1},{"id":"257-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques des œdèmes liés à une rétention hydrosodée","contenu":"<div class=\"callout callout-info\">\n        <strong>Repère quantitatif.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-clinique\">œdèmes</span> deviennent francs lorsque la rétention atteint <span class=\"kw-chiffre\">≥ 3–5 % du poids du corps</span> (≈ <span class=\"kw-chiffre\">2,5–3 L</span>). Les <span class=\"kw-clinique\">œdèmes</span> généralisés traduisent une augmentation du volume interstitiel <span class=\"kw-chiffre\">&gt; 10 %</span> (soit <span class=\"kw-chiffre\">1–2 kg</span> chez un adulte de <span class=\"kw-chiffre\">70 kg</span>).\n      </div>\n      <table >\n        <thead><tr><th>Caractère</th><th>Syndrome œdémateux de rétention</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Siège</strong></td><td>Tissus <span class=\"kw-clinique\">sous-cutanés</span></td></tr>\n          <tr><td><strong>Latéralité</strong></td><td><span class=\"kw-clinique\">Bilatéraux</span> et <span class=\"kw-clinique\">symétriques</span></td></tr>\n          <tr><td><strong>Palpation</strong></td><td><span class=\"kw-clinique\">Mous</span>, prenant le <span class=\"kw-clinique\">godet</span> (dépression à la pression contre le tibia)</td></tr>\n          <tr><td><strong>Coloration</strong></td><td><span class=\"kw-clinique\">Blancs</span></td></tr>\n          <tr><td><strong>Douleur</strong></td><td><span class=\"kw-clinique\">Indolores</span></td></tr>\n          <tr>\n            <td><strong>Topographie déclive</strong></td>\n            <td>\n              <strong>Orthostatisme :</strong> membres inférieurs (chevilles → effacement du sillon rétro-malléolaire)<br>\n              <strong>Alitement prolongé :</strong> lombes, ou <span class=\"kw-clinique\">œdème</span> palpébral / péri-orbitaire chez le sujet jeune\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span> chronique</strong></td>\n            <td><span class=\"kw-clinique\">Œdèmes</span> pouvant devenir <span class=\"kw-clinique\">durs et douloureux</span> ; <span class=\"kw-clinique\">lésions cutanées cyanotiques de stase</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p style=\"margin: 12px 0 6px; font-size: 13px;\"><strong>Atteinte des autres secteurs :</strong></p>\n      <table >\n        <tbody>\n          <tr><td><strong>Secteur vasculaire</strong></td><td><span class=\"kw-clinique\">Élévation de la PA</span> ; <span class=\"kw-alerte\">OAP</span> si élévation rapide de la volémie</td></tr>\n          <tr><td><strong>Séreuses</strong></td><td>Épanchement <span class=\"kw-clinique\">pleural transsudatif</span> ; <span class=\"kw-clinique\">ascite</span>, hydrocèle (surtout enfant) ; épanchement <span class=\"kw-clinique\">péricardique</span> (exceptionnel)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Suivi</span>.</strong> La <span class=\"kw-clinique\"><strong>prise de poids</strong></span> évalue l'importance du syndrome œdémateux (au mieux en l'absence de variation de la <span class=\"kw-bio\">natrémie</span>). La <span class=\"kw-clinique\"><strong>pesée régulière</strong></span> est le meilleur paramètre pour juger l'efficacité du traitement.\n      </div>","frequence":1},{"id":"257-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les principaux signes biologiques à rechercher devant des œdèmes","contenu":"<div class=\"callout callout-warn\">\n        <strong>Point clé.</strong> <span class=\"kw-clinique\">Les</span> signes biologiques du syndrome œdémateux sont <span class=\"kw-alerte\">pauvres</span> : on peut retrouver une <span class=\"kw-bio\">hémodilution</span> (anémie, hypoprotidémie), inconstante et dépendante des valeurs de base. <span class=\"kw-alerte\">Aucun signe biologique ne reflète directement le volume du secteur interstitiel.</span> Les examens servent surtout à l'<strong>orientation étiologique</strong>.\n      </div>\n      <p style=\"margin: 12px 0 6px; font-size: 13px;\"><strong>Bilan <span class=\"kw-ttt\">biologique</span> d'orientation étiologique :</strong></p>\n      <table >\n        <thead><tr><th>Orientation</th><th>Signes biologiques à rechercher</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Rénale</strong></td>\n            <td><span class=\"kw-bio\">BU</span> ; <span class=\"kw-bio\">sédiment urinaire</span> ; protidémie et <span class=\"kw-bio\">albuminémie</span> ; <span class=\"kw-bio\">créatininémie + DFG</span> — une <span class=\"kw-clinique\">hypoalbuminémie</span> + <span class=\"kw-clinique\">protéinurie abondante</span> (± <span class=\"kw-bio\">hématurie</span>) évoque un <span class=\"kw-etio\">syndrome néphrotique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hépatique</strong></td>\n            <td>Albuminémie ; <span class=\"kw-bio\">TP</span> (± <span class=\"kw-bio\">facteur V</span>) ; <span class=\"kw-bio\">bilan hépatique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Cardiaque</strong></td>\n            <td>Élévation du <span class=\"kw-bio\">BNP</span> ou <span class=\"kw-bio\">NT-proBNP</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hypoalbuminémie (défaut de synthèse / perte)</strong></td>\n            <td>Albuminémie ↓ ; protéines nutritionnelles (<span class=\"kw-bio\">pré-albumine</span>, <span class=\"kw-bio\">transferrine</span>) basses → <span class=\"kw-clinique\">anorexie</span> / malabsorption ; recherche de fuite (<span class=\"kw-bio\">protéinurie</span>, entéropathie exsudative)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Surveillance</span> sous traitement.</strong> <span class=\"kw-bio\">Ionogramme sanguin et urinaire</span>, <span class=\"kw-bio\">natriurèse / 24 h</span>, <span class=\"kw-bio\">créatinine</span> et <span class=\"kw-bio\">urée</span> (recherche d'hémoconcentration / hypovolémie <span class=\"kw-etio\">iatrogène</span> sous <span class=\"kw-ttt\">diurétiques</span>).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-bio\">Protéinurie</span> et <span class=\"kw-clinique\">syndrome néphrotique</span> · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":3},{"id":"257-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies et les signes cliniques des œdèmes localisés et généralisés","contenu":"<h4 style=\"margin: 0 0 8px; font-size: 13.5px; border-left: 3px solid var(--mat); padding-left: 8px;\"><span class=\"kw-clinique\">Œdèmes</span> localisés</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Étiologies / signes cliniques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Inflammatoire</strong></span></td>\n            <td><span class=\"kw-etio\">Érysipèle</span> (infection cutanée) ; <span class=\"kw-etio\">algodystrophie</span> ; <span class=\"kw-etio\">piqûre d'insecte</span>, <span class=\"kw-etio\">traumatisme</span>, <span class=\"kw-etio\">allergie</span> — aspect rouge, chaud, douloureux</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Non inflammatoire — obstacle veineux</strong></span></td>\n            <td><span class=\"kw-etio\">TVP</span> ; <span class=\"kw-etio\">insuffisance veineuse</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Non inflammatoire — lymphœdème</strong></span></td>\n            <td><span class=\"kw-etio\">Filariose</span> ; <span class=\"kw-etio\">cancer</span> (<span class=\"kw-bio\">envahissement</span> ganglionnaire, curage, <span class=\"kw-ttt\">radiothérapie</span>) ; <span class=\"kw-etio\">anomalie primitive des vaisseaux lymphatiques</span> (plutôt bilatéraux) — <span class=\"kw-clinique\">œdème</span> dur, cartonné</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Médicaments</strong></span></td>\n            <td>\n              <strong><span class=\"kw-ttt\">Inhibiteurs calciques</span> dihydropyridine :</strong> ↑ perméabilité capillaire<br>\n              <strong><span class=\"kw-ttt\">IEC</span> / <span class=\"kw-ttt\">ARA2</span>, <span class=\"kw-ttt\">gliptines</span>, COP :</strong> <span class=\"kw-clinique\">angiœdème bradykinique</span> — blancs, mous, non prurigineux, touchant volontiers la face, avec troubles digestifs associés\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ci\"><strong>Faux œdème — à distinguer</strong></span></td>\n            <td><span class=\"kw-etio\">Myxœdème</span> de l'hypothyroïdie : <strong>n'est pas un véritable <span class=\"kw-clinique\">œdème</span></strong> — peau <span class=\"kw-clinique\">pâle, sèche, cireuse</span>, ne prenant pas le godet</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin: 14px 0 8px; font-size: 13.5px; border-left: 3px solid var(--mat); padding-left: 8px;\"><span class=\"kw-clinique\">Œdèmes</span> généralisés (hyperhydratation extracellulaire)</h4>\n      <table >\n        <thead><tr><th>Cause</th><th>Étiologies / signes cliniques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Rein</strong></span></td>\n            <td><span class=\"kw-etio\">Syndrome néphrotique</span> ; <span class=\"kw-etio\">IRA</span> (surtout GNA post-infectieuse) ; <span class=\"kw-etio\">IRC</span> (<span class=\"kw-def\">stade</span> pré-terminal) — <span class=\"kw-etio\">HTA</span>, <span class=\"kw-bio\">hématurie</span>, <span class=\"kw-bio\">protéinurie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Cœur</strong></span></td>\n            <td><span class=\"kw-etio\">Insuffisance cardiaque droite</span> — <span class=\"kw-clinique\">turgescence jugulaire</span>, <span class=\"kw-clinique\">reflux hépato-jugulaire</span>, <span class=\"kw-clinique\">dyspnée</span>, épanchements pleuraux (surtout à droite)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Foie</strong></span></td>\n            <td><span class=\"kw-etio\">Cirrhose hépatique</span> — <span class=\"kw-clinique\">ascite</span> (<span class=\"kw-alerte\">décompensation</span> œdémato-ascitique), contexte d'intoxication éthylique / hépatite</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Hypoalbuminémie</strong></span></td>\n            <td>Dénutrition (kwashiorkor, marasme) ; malabsorption ; défaut de synthèse (<span class=\"kw-alerte\">insuffisance hépatocellulaire</span>) ; perte (<span class=\"kw-clinique\">syndrome néphrotique</span>, brûlure étendue) ; affection catabolisante (cancer, infection chronique)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Autres</strong></span></td>\n            <td><span class=\"kw-etio\">Pré-éclampsie</span> (<span class=\"kw-etio\">HTA</span> + <span class=\"kw-clinique\">œdèmes</span>, 3<sup>e</sup> trimestre) ; <span class=\"kw-etio\">troubles de la perméabilité capillaire</span> (médicaments, <span class=\"kw-alerte\">choc septique</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Idiopathique</strong></span></td>\n            <td><span class=\"kw-etio\">Œdèmes cycliques idiopathiques</span> (diagnostic d'élimination) : femme en période d'activité génitale ; prise de poids rapide (<span class=\"kw-chiffre\">1,5–2 kg</span>) ; lié au cycle menstruel ; oligurie</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-clinique\">Syndrome néphrotique</span> · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span> · 279 — Cirrhose · 226 — Maladie veineuse thrombo-<span class=\"kw-etio\">embolique</span> · 350 — Grosse jambe rouge aiguë (<span class=\"kw-clinique\">érysipèle</span>)</em></p>","frequence":0},{"id":"257-8","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement symptomatique des syndromes œdémateux","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif.</strong> Le traitement symptomatique vise à induire un <span class=\"kw-chiffre\"><strong>bilan sodé négatif</strong></span> (en parallèle du traitement étiologique).\n      </div>\n      <table >\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>re</sup> intention</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Régime restreint en sel</span> : <span class=\"kw-chiffre\">2–4 g de NaCl/j</span> (≈ 35–<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>70</span> mmol</span> de Na) — moins restreint s'il entraîne une <span class=\"kw-clinique\">anorexie</span></li>\n                <li><span class=\"kw-ttt\">Diurétiques de l'anse</span> (effet natriurétique le plus puissant) : <span class=\"kw-ttt\">furosémide</span>, <span class=\"kw-ttt\">bumétanide</span></li>\n                <li><span class=\"kw-ttt\">Alitement initial</span> possible si syndrome œdémateux important (réduit la stimulation du SRAA)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Si résistance</strong></td>\n            <td>\n              Blocage d'autres sites distaux, sous <span class=\"kw-def\">surveillance</span> étroite (<span class=\"kw-bio\">kaliémie</span>, volémie) :\n              <ul>\n                <li><span class=\"kw-ttt\">Amiloride</span> (tube collecteur) : surtout efficace dans le <span class=\"kw-etio\">syndrome néphrotique</span> — <span class=\"kw-ci\">CI si insuffisance rénale</span> (risque d'hyperkaliémie)</li>\n                <li><span class=\"kw-ttt\">Thiazidiques</span> (tube contourné distal) : effet synergique sur la kaliurèse → risque d'<span class=\"kw-alerte\">hypokaliémie</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Surveillance</span></strong></td>\n            <td>\n              <strong>Efficacité :</strong> poids, <span class=\"kw-clinique\">œdèmes</span>, PA debout-couché, diurèse, natriurèse/<span class=\"kw-chiffre\">24 h</span> — réponse <span class=\"kw-clinique\">progressive</span> (une déplétion trop rapide expose à l'<span class=\"kw-alerte\">hypovolémie</span> et au risque de <span class=\"kw-etio\">TVP</span> par hémoconcentration)<br>\n              <strong>Tolérance :</strong> <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">ionogramme</span>, hémoconcentration\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ci\"><strong>Chez l'enfant</strong></span></td>\n            <td><span class=\"kw-clinique\">Syndrome néphrotique</span> → <span class=\"kw-ci\">éviter les diurétiques</span> (risque de majoration de l'hypovolémie et de l'hypercoagulabilité) ; <span class=\"kw-clinique\">les</span> réserver aux <span class=\"kw-clinique\">œdèmes</span>/épanchements importants avec retentissement clinique</td>\n          </tr>\n          <tr>\n            <td><strong>Exceptionnel</strong></td>\n            <td>Perfusions d'<span class=\"kw-ttt\">albumine</span> : réservées aux situations exceptionnelles d'<span class=\"kw-alerte\">hypotension symptomatique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 267 — Hyperhydratation extracellulaire · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des <span class=\"kw-ttt\">diurétiques</span></em></p>","frequence":1}],"astuces":[],"strategie":{"redflags":"<ul><li><span class=\"kw-alerte\">OAP</span> par élévation rapide de la volémie (retentissement sur le secteur vasculaire)</li><li><span class=\"kw-alerte\">Anasarque</span> : <span class=\"kw-clinique\">œdèmes</span> généralisés + épanchement des <span class=\"kw-clinique\">séreuses</span> (<span class=\"kw-clinique\">pleural</span> ± <span class=\"kw-clinique\">ascite</span> ± <span class=\"kw-clinique\">péricardique</span>) — forme la plus grave</li><li><span class=\"kw-clinique\">HTA</span> + <span class=\"kw-clinique\">œdèmes</span> au <span class=\"kw-chiffre\">3<sup>e</sup> trimestre</span> de <span class=\"kw-ci\">grossesse</span> → <span class=\"kw-alerte\">pré-éclampsie</span></li><li><span class=\"kw-alerte\">Hypotension symptomatique</span> traduisant une hypovolémie sévère</li><li>Sous <span class=\"kw-ttt\">diurétiques</span> : déplétion trop rapide → <span class=\"kw-alerte\">hypovolémie</span> (hémoconcentration) et risque de <span class=\"kw-etio\">TVP</span></li><li><span class=\"kw-alerte\">Hypokaliémie</span> lors de l'association <span class=\"kw-ttt\">diurétique de l'anse</span> + <span class=\"kw-ttt\">thiazidique</span></li></ul>","principes":"<p>Objectif = induire un <span class=\"kw-chiffre\">bilan sodé négatif</span>, en parallèle du <strong>traitement étiologique</strong>. La déplétion doit rester <span class=\"kw-clinique\">progressive</span> : une déplétion trop rapide expose à l'<span class=\"kw-alerte\">hypovolémie</span>.</p><p><strong>1<sup>re</sup> intention</strong></p><ul><li><span class=\"kw-ttt\">Régime restreint en sel</span> : <span class=\"kw-chiffre\">2–4 g de NaCl/j</span> (≈ <span class=\"kw-chiffre\">35–70 mmol</span> de Na) — moins restreint s'il entraîne une <span class=\"kw-clinique\">anorexie</span></li><li><span class=\"kw-ttt\">Diurétiques de l'anse</span> (effet natriurétique le plus puissant) : <span class=\"kw-ttt\">furosémide</span>, <span class=\"kw-ttt\">bumétanide</span></li><li><span class=\"kw-ttt\">Alitement initial</span> possible si syndrome œdémateux important (réduit la stimulation du <span class=\"kw-clinique\">SRAA</span>)</li></ul><p><strong>Si résistance <span class=\"q\">— blocage de sites distaux</span></strong></p><p>sous <span class=\"kw-def\">surveillance</span> étroite (<span class=\"kw-bio\">kaliémie</span>, volémie)</p><ul><li><span class=\"kw-ttt\">Amiloride</span> (tube collecteur) : surtout efficace dans le <span class=\"kw-etio\">syndrome néphrotique</span> — <span class=\"kw-ci\">CI si insuffisance rénale</span> (risque d'hyperkaliémie)</li><li><span class=\"kw-ttt\">Thiazidiques</span> (tube contourné distal) : effet synergique sur la kaliurèse → risque d'<span class=\"kw-alerte\">hypokaliémie</span></li></ul><p><strong>Chez l'enfant <span class=\"q\">— <span class=\"kw-clinique\">syndrome néphrotique</span></span></strong></p><ul><li><span class=\"kw-ci\">Éviter les diurétiques</span> (risque de majoration de l'hypovolémie et de l'hypercoagulabilité)</li><li><span class=\"kw-clinique\">Les</span> réserver aux <span class=\"kw-clinique\">œdèmes</span> / épanchements importants avec retentissement clinique</li></ul><p><strong>Situation exceptionnelle</strong></p><ul><li>Perfusions d'<span class=\"kw-ttt\">albumine</span> : réservées aux situations exceptionnelles d'<span class=\"kw-alerte\">hypotension symptomatique</span></li></ul>","suivi":"<p>La <strong>pesée régulière</strong> est le meilleur paramètre pour juger l'efficacité du traitement (au mieux à <span class=\"kw-bio\">natrémie</span> stable).</p><p><strong>Efficacité</strong></p><ul><li><span class=\"kw-clinique\">Poids</span>, <span class=\"kw-clinique\">œdèmes</span>, <span class=\"kw-clinique\">PA debout-couché</span>, <span class=\"kw-clinique\">diurèse</span>, <span class=\"kw-bio\">natriurèse / 24 h</span></li><li>Réponse <span class=\"kw-clinique\">progressive</span> attendue (déplétion trop rapide → <span class=\"kw-alerte\">hypovolémie</span> + <span class=\"kw-etio\">TVP</span> par hémoconcentration)</li></ul><p><strong>Tolérance</strong></p><ul><li><span class=\"kw-bio\">Créatinine</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">ionogramme sanguin et urinaire</span></li><li>Recherche d'<span class=\"kw-clinique\">hémoconcentration</span> / hypovolémie <span class=\"kw-etio\">iatrogène</span> sous <span class=\"kw-ttt\">diurétiques</span></li></ul>"},"liensGlobaux":[{"href":"https://manuel4.cuen.fr/spip.php?rubrique12","label":"Collège CUEN — Œdèmes des membres inférieurs"}],"cards":[]};